/* ---------- armazenamento ---------- */
const KEY='mdl_v1';
function loadDB(){try{const d=JSON.parse(localStorage.getItem(KEY));if(d&&d.v===1)return d}catch(e){}
 return{v:1,player:null,players:{},set:{sound:true,voice:true,letters:'upper',unlock:false},pin:'',custom:{vog:[],con:[],f31:[],f32:[]}}}
let DB=loadDB();
function save(){try{localStorage.setItem(KEY,JSON.stringify(DB))}catch(e){}}
function me(){const n=DB.player;if(!n)return null;if(!DB.players[n])DB.players[n]={prog:{},inf:{}};return DB.players[n]}
function stars(mode,n){const p=me();return(p&&p.prog[mode]&&p.prog[mode][n-1])||0}
function setStars(mode,n,s){const p=me();if(!p)return;const a=p.prog[mode]||(p.prog[mode]=[]);if((a[n-1]||0)<s)a[n-1]=s;save()}
/* ---------- dicionário ---------- */
const DSET=new Set();let dictReady=false;
function buildDict(){if(dictReady)return;dictReady=true;try{let prev='';String(window.DICT_TXT||'').split('\n').forEach(l=>{if(!l)return;const cur=prev.slice(0,+l[0])+l.slice(1);DSET.add(cur);prev=cur});(window.BADW||[]).forEach(b=>DSET.delete(b))}catch(e){}}
const WORDS=String(window.WDB||'').split('\n').filter(Boolean).map(l=>{const p=l.split('|');return{w:p[0],s:p[1].split('-'),t:+p[2]}});
const CSET=new Set(WORDS.map(o=>norm(o.w)));
const WMAP={};WORDS.forEach(o=>{WMAP[o.w]=o.s});
/* ---------- silabação (professor) ---------- */
const VOG='aeiouáéíóúâêôãõà',CODA='lrsmnzx';
const ONS2=new Set('pr br tr dr cr gr fr vr pl bl cl gl fl ch lh nh'.split(' '));
const FALL=new Set('ai ei oi au eu ou ái éi ói éu áu âu êi ôi êu ão õe ãe'.split(' '));
function syllabify(w){
 w=w.toLowerCase();if(!/^[a-záéíóúâêôãõàç]+$/.test(w))return null;
 const w2=w.replace(/([qg])u([aeioáéíóâêô])/g,'$1\x01$2');
 const toks=[];let i=0;
 while(i<w2.length){const c=w2[i];
  if(c==='\x01'){toks.push(['C','u']);i++;continue}
  if(VOG.indexOf(c)>=0){let j=i;while(j<w2.length&&VOG.indexOf(w2[j])>=0)j++;const run=w2.slice(i,j);
   if(run.length===1||FALL.has(run))toks.push(['V',run]);else return null;i=j}
  else{toks.push(['C',c]);i++}}
 const nuc=[];toks.forEach((t,k)=>{if(t[0]==='V')nuc.push(k)});
 if(!nuc.length)return null;
 const syl=[];let start=0;
 for(let x=0;x<nuc.length;x++){
  if(x===nuc.length-1){syl.push(toks.slice(start).map(t=>t[1]).join(''));break}
  const k=nuc[x],k2=nuc[x+1];const cs=toks.slice(k+1,k2).map(t=>t[1]).join('');
  if(!cs.length)return null;
  let cut=0;
  if(cs.length>1){let on=1;const l2=cs.slice(-2);
   if(ONS2.has(l2))on=2;else if(l2==='qu'||l2==='gu')on=2;
   if(['rr','ss','sc','sç','xc'].indexOf(l2)>=0)on=1;
   cut=cs.length-on;const coda=cs.slice(0,cut);
   for(const ch of coda)if(CODA.indexOf(ch)<0)return null;
   if((l2==='sc'||l2==='xc')&&cs.length===2)cut=1}
  const end=k+1+cut;syl.push(toks.slice(start,end).map(t=>t[1]).join(''));start=end}
 const s=syl.map(x=>x.replace(/\x01/g,'u'));
 return s.join('')===w?s:null}
function sylAuto(w){w=w.toLowerCase();const n=norm(w);if(WMAP[w])return WMAP[w];const s=syllabify(w);if(s)return s;
 const m=w.match(/[^aeiouáéíóúâêôãõà]*[aeiouáéíóúâêôãõà]+(?:[lrsmnzx](?![aeiouáéíóúâêôãõà]))?/g);return m&&m.join('')===w?m:[w]}
function onsetOf(s){const m=norm(s).toLowerCase().match(/^(qu|gu|ch|lh|nh|pr|br|tr|dr|cr|gr|fr|vr|pl|bl|cl|gl|fl|[bcdfghjklmnpqrstvwxyz])/);return m?m[1]:''}
/* ---------- som e voz ---------- */
let AC=null;
function tone(f,d,t,v){if(!DB.set.sound)return;try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();const o=AC.createOscillator(),g=AC.createGain();o.type=t||'sine';o.frequency.value=f;g.gain.value=v||.08;o.connect(g);g.connect(AC.destination);const n=AC.currentTime;g.gain.setValueAtTime(v||.08,n);g.gain.exponentialRampToValueAtTime(.0001,n+d);o.start(n);o.stop(n+d)}catch(e){}}
const Snd={match(c){const b=[523,587,659,698,784,880,988][Math.min(6,(c||1)-1)];tone(b,.16,'triangle',.1);setTimeout(()=>tone(b*1.5,.18,'triangle',.07),70)},bad(){tone(180,.18,'sawtooth',.05)},win(){[523,659,784,1047].forEach((f,i)=>setTimeout(()=>tone(f,.25,'triangle',.1),i*130))},lose(){[392,330,262].forEach((f,i)=>setTimeout(()=>tone(f,.3,'sine',.09),i*170))},tick(){tone(900,.05,'square',.03)}};
let VOICE=null;
const LNAME={a:'á',e:'ê',i:'i',o:'ó',u:'u',b:'bê',c:'cê',d:'dê',f:'efe',g:'gê',h:'agá',j:'jota',k:'cá',l:'ele',m:'eme',n:'ene',p:'pê',q:'quê',r:'erre',s:'esse',t:'tê',v:'vê',w:'dáblio',x:'xis',y:'ípsilon',z:'zê'};
function sylSay(s){s=String(s).toLowerCase();const m=s.match(/^([^aeiouáéíóúâêôãõà]*)([aeiou])$/);if(m)return m[1]+{a:'á',e:'ê',i:'í',o:'ô',u:'ú'}[m[2]];return s}
function speakTile(label){const l=String(label).toLowerCase();if(l.length===1)speak(LNAME[l]||l);else speak(sylSay(l))}
function speak(t){if(!DB.set.voice||!window.speechSynthesis)return;try{const s=window.speechSynthesis;s.cancel();const u=new SpeechSynthesisUtterance(String(t));u.lang='pt-BR';u.rate=.85;if(!VOICE){const vs=s.getVoices();VOICE=vs.find(v=>/pt-BR/i.test(v.lang))||vs.find(v=>/^pt/i.test(v.lang))||null}if(VOICE)u.voice=VOICE;s.speak(u)}catch(e){}}
let toastT=0;
function toast(m,ms){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove('on'),ms||1800)}
function wtoast(m){const t=$('#wtoast');t.textContent=m;t.classList.remove('on');void t.offsetWidth;t.classList.add('on')}

/* ===== definição dos modos e geração de níveis ===== */
const MODES={
 vog:{id:'vog',name:'Modo Vogal',short:'Vogais',ico:'A',color:'#22d3ee',desc:'Junte 3 ou mais vogais iguais',how:'Troque duas peças vizinhas para juntar 3 ou mais vogais iguais, na linha ou na coluna.'},
 con:{id:'con',name:'Modo Consoante',short:'Consoantes',ico:'B',color:'#f472b6',desc:'Junte 3 ou mais consoantes iguais',how:'Troque duas peças vizinhas para juntar 3 ou mais consoantes iguais. Só contam as letras da missão!'},
 f31:{id:'f31',name:'Sílabas iguais',short:'Sílabas iguais',ico:'BA',color:'#a78bfa',desc:'Junte 3 ou mais sílabas iguais',how:'Troque duas peças vizinhas para juntar 3 ou mais sílabas iguais da família da missão.'},
 f32:{id:'f32',name:'Juntar sílabas',short:'Juntar sílabas',ico:'CA·SA',color:'#facc15',desc:'Una sílabas e forme palavras',how:'Deixe sílabas lado a lado (da esquerda para a direita ou de cima para baixo) para formar uma palavra. Troque peças vizinhas para organizar!'}
};
const MKEYS=['vog','con','f31','f32'];
const PAL=[['#22d3ee','#0ea5b7'],['#a78bfa','#7c5ce0'],['#f472b6','#d9468f'],['#facc15','#d99e0a'],['#34d399','#14a374'],['#fb923c','#e0661a'],['#60a5fa','#3b7be0'],['#f87171','#d94545'],['#c084fc','#9a55e0'],['#2dd4bf','#16a89a']];
const secsFor=n=>300+Math.round((n-1)*600/29);
const VL={a:['A','a','Á','á','Â','â','Ã','ã'],e:['E','e','É','é','Ê','ê'],i:['I','i','Í','í'],o:['O','o','Ó','ó','Ô','ô','Õ','õ'],u:['U','u','Ú','ú']};
const VKEYS=['a','e','i','o','u'];
const CORD='ptmbdfvlnsrcgjzxhq'.split('');
const CONFUSE={p:'b',b:'d',d:'b',t:'d',f:'v',v:'f',m:'n',n:'m',s:'z',z:'s',c:'g',g:'c',q:'g',l:'r',r:'l',j:'g',x:'z',h:'n'};
const FAM=['P','T','M','B','D','F','V','L','N','S','C','G','R','J','Z','X','CH','LH','NH','QU','GU','BR','PR','TR','CR','DR','FR','GR','BL','PL'];
function famSyl(f){f=f.toLowerCase();return(f==='qu'||f==='gu'?['a','e','i','o']:['a','e','i','o','u']).map(v=>f+v)}
function mkSym(keys,labelsOf,targets){/* keys: array de chaves; devolve símbolos com cor por rótulo */
 const syms=[];let ci=0;const cmap={};
 keys.forEach(k=>{const labels=labelsOf(k);labels.forEach(l=>{if(cmap[l]===undefined)cmap[l]=ci++});syms.push({key:k,labels:labels,target:targets.indexOf(k)>=0,w:targets.indexOf(k)>=0?1.3:1,cols:labels.map(l=>cmap[l]%PAL.length)})});return syms}
function split(total,k){const o=[];let r=total;for(let i=0;i<k;i++){const v=Math.round(r/(k-i));o.push(v);r-=v}return o}
/* vogais e consoantes */
function buildVC(mode,targets,o){
 const rng=o.rng;let keys=targets.slice();
 if(mode==='vog'){const others=shuf(VKEYS.filter(v=>targets.indexOf(v)<0),rng);
  let nv=Math.max(0,Math.min(others.length,o.kinds-targets.length-(o.cons===undefined?2:o.cons)));
  if(o.dtype==='opp')nv=0;if(o.dtype==='same')nv=Math.min(others.length,o.kinds-targets.length);
  keys=keys.concat(others.slice(0,nv));
  const cs=shuf('bmlstpcdrnfv'.split(''),rng);let ci=0;while(keys.length<o.kinds&&ci<cs.length)keys.push('c:'+cs[ci++])}
 else{const vs=shuf(['a','e','o','i','u'],rng);let d=[];
  if(o.kinds>4&&o.conf&&o.dtype!=='opp'){targets.forEach(t=>{const c=CONFUSE[t];if(c&&targets.indexOf(c)<0&&d.indexOf(c)<0)d.push(c)})}
  let nvow=o.kinds<=5?2:1;if(o.dtype==='opp')nvow=Math.min(5,o.kinds-targets.length);if(o.dtype==='same')nvow=0;for(let i=0;i<nvow;i++)d.push('v:'+vs[i]);
  const cs=shuf(CORD.filter(c=>targets.indexOf(c)<0&&d.indexOf(c)<0),rng);let ci=0;
  while(d.length<o.kinds-targets.length)d.push(cs[ci++]);
  keys=keys.concat(d.slice(0,o.kinds-targets.length))}
 const labelsOf=k=>{
  if(mode==='vog'){const b=k.indexOf('c:')===0?k.slice(2):k;const isV=VL[b]&&k.indexOf('c:')!==0;
   if(isV){const L=VL[b];return o.lab==='u'?[L[0]]:o.lab==='m'?[L[0],L[1]]:L}
   return o.lab==='u'?[b.toUpperCase()]:[b.toUpperCase(),b]}
  const b=k.indexOf('v:')===0?k.slice(2):k;return o.lab==='u'?[b.toUpperCase()]:[b.toUpperCase(),b]};
 const syms=mkSym(keys,labelsOf,targets);
 syms.forEach(s=>{s.cat=mode==='vog'?VKEYS.indexOf(s.key)>=0:s.key.indexOf('v:')!==0;if(!s.cat)s.w=.6});
 const ns=split(o.total,targets.length);
 const names=targets.map(t=>t.toUpperCase());
 return{rows:o.size||6,cols:o.size||6,mode:mode,kind:'same',title:o.title,sub:o.sub||('Reúna '+o.total+' '+(mode==='vog'?(targets.length>1?'vogais ':'vogais '):'consoantes ')+names.join(', ')),secs:o.secs,symbols:syms,
  goals:targets.map((t,i)=>({key:t,n:ns[i],label:t.toUpperCase()+(mode==='vog'?'':'')})),tip:o.tip||''}}
/* famílias silábicas (sílabas iguais) */
function buildF31(fam,o){
 const rng=o.rng;const sy=o.syls||famSyl(fam);const fs=new Set(o.fams||[String(fam).toUpperCase()]);
 const ext=[];const nd=o.nd||0;
 if(nd>0){const pool=[];FAM.forEach(f=>{if(!fs.has(f))famSyl(f).forEach(x=>pool.push(x))});
  for(const x of shuf(pool,rng)){if(ext.length>=nd)break;if(sy.indexOf(x)<0&&ext.indexOf(x)<0)ext.push(x)}}
 const keys=sy.concat(ext);
 const syms=mkSym(keys,k=>[k],sy);
 syms.forEach(s=>{s.cat=s.target;if(!s.cat)s.w=.55});
 const nm=o.famName||String(fam).toUpperCase();
 return{rows:o.size||6,cols:o.size||6,mode:'f31',kind:'same',title:o.title,sub:o.sub||('Reúna '+o.total+' sílabas da família do '+nm),secs:o.secs,symbols:syms,goals:[{key:'*',n:o.total,label:'sílabas '+nm}],tip:''}}
/* juntar sílabas */
function pickWords(n,rng,K){
 const tier=n<=10?1:n<=20?2:3;const minS=2,maxS=n<=10?2:n<=20?3:4;
 let k=Math.min(18,4+n);let cand=[];
 for(;;){const al=new Set(CORD.slice(0,k).concat(tier>=2?['ch','lh','nh','qu','gu','pr','br','tr','dr','cr','gr','fr','pl','bl','cl','gl','fl','vr']:[]));
  cand=WORDS.filter(o=>o.t<=tier&&o.s.length>=minS&&o.s.length<=maxS&&o.s.every(s=>{const on=onsetOf(s);return on===''||al.has(on)}));
  if(cand.length>=K*3||k>=18)break;k++}
 cand=cand.slice(0,Math.max(60,K*8));
 const out=[];const seenS=new Set();
 for(const o of shuf(cand,rng)){if(out.length>=K)break;if(seenS.has(o.s[0]+o.s.length))continue;seenS.add(o.s[0]+o.s.length);out.push(o)}
 for(const o of shuf(cand,rng)){if(out.length>=K)break;if(out.indexOf(o)<0)out.push(o)}
 return out}
function buildF32(words,o){/* words: [{w,s:[...]}] */
 const strict=!!o.strict;const rng=o.rng;
 const syl={};words.forEach(w=>w.s.forEach(s=>{const k=norm(s);if(!syl[k])syl[k]=s.toLowerCase()}));
 let keys=Object.keys(syl);
 const dis=[];const ND=Math.max(o.nd===undefined?5:o.nd,16-keys.length);if(!o.noDistract&&ND>0){const extra=shuf(WORDS.slice(0,900).filter(x=>x.s.length>=2&&x.s.length<=3),rng);for(const x of extra){if(dis.length>=ND)break;const s=x.s[Math.floor(rng()*x.s.length)];const k=norm(s);if(!syl[k]&&dis.indexOf(k)<0){dis.push(k);syl[k]=s.toLowerCase()}}}
 const all=keys.concat(dis);
 const syms=all.map(k=>{let h=0;for(let i=0;i<k.length;i++)h=(h*31+k.charCodeAt(i))>>>0;return{key:k,labels:[syl[k]],target:keys.indexOf(k)>=0,w:keys.indexOf(k)>=0?1:.5,cols:[h%PAL.length],syl:true}});
 const wl=words.map(w=>({w:norm(w.w.replace(/-/g,'')),disp:w.s.join('·').toLowerCase(),s:w.s.map(norm),done:false}));
 const goalN=strict?wl.length:Math.min(o.goal||wl.length,99);
 return{rows:o.size||6,cols:o.size||6,mode:'f32',kind:'words',title:o.title,sub:o.sub||(strict?('Forme as '+wl.length+' palavras da lista'):('Forme '+goalN+' palavras diferentes')),secs:o.secs,symbols:syms,words:wl,strict:strict,goalN:goalN,goals:[],tip:''}}
/* ---------- níveis fixos ---------- */
const VPAIRS=[['a','e'],['e','i'],['i','o'],['o','u'],['a','o']],VTRI=[['a','e','i'],['e','i','o'],['i','o','u'],['a','e','o'],['a','i','u']];
const CPAIRS=[['p','b'],['t','d'],['f','v'],['c','g'],['m','n'],['s','z']],CTRI=[['b','d','p'],['m','n','l'],['f','v','s'],['c','g','r'],['j','x','z'],['r','s','l','n']];
function levelSpec(mode,n){
 const rng=mulberry(n*7919+MKEYS.indexOf(mode)*104729+13),secs=secsFor(n),title='Nível '+n;
 if(mode==='vog'){let t,lab,kinds;
  if(n<=10){t=[VKEYS[(n-1)%5]];lab='u';kinds=n<=5?4:5}
  else if(n<=15){t=[VKEYS[(n-11)%5]];lab='m';kinds=5}
  else if(n<=20){t=VPAIRS[n-16];lab='m';kinds=6}
  else if(n<=25){t=VTRI[n-21];lab='m';kinds=6}
  else{t=VKEYS.slice();lab='a';kinds=7;if(n<30)t=shuf(VKEYS,rng).slice(0,4)}
  return buildVC('vog',t,{rng:rng,kinds:kinds,lab:lab,total:25+Math.round(n*1.5),secs:secs,title:title,cons:n<=5?2:undefined})}
 if(mode==='con'){let t,lab,kinds=Math.min(7,4+Math.floor((n-1)/8));
  if(n<=18)t=[CORD[n-1]];else if(n<=24)t=CPAIRS[n-19];else t=CTRI[n-25];
  lab=n<=10?'u':'m';
  return buildVC('con',t,{rng:rng,kinds:Math.max(kinds,t.length+3),lab:lab,total:25+Math.round(n*1.5),secs:secs,title:title,conf:n>6})}
 if(mode==='f31'){const f=FAM[n-1];return buildF31(f,{rng:rng,total:25+Math.round(n*1.5),secs:secs,title:title,nd:n<=10?3:n<=20?4:5})}
 const K=5+Math.floor((n-1)/5);const w=pickWords(n,rng,K);
 return buildF32(w,{rng:rng,goal:Math.min(40,18+Math.round(n*.75)),secs:secs,title:title})}
/* ---------- infinito ---------- */
function infSpec(mode,k){
 const seed=(Date.now()^(k*977))>>>0,rng=mulberry(seed);const secs=480+(k%6)*60,title='Infinito '+k;
 const lev=Math.min(30,10+k*2);
 if(mode==='vog'){const nt=1+Math.floor(rng()*3);const t=shuf(VKEYS,rng).slice(0,nt);return buildVC('vog',t,{rng:rng,kinds:Math.min(7,5+(nt>1?1:0)+Math.floor(k/4)),lab:rng()<.5?'m':'a',total:40+Math.round(lev*1.2),secs:secs,title:title})}
 if(mode==='con'){const nt=1+Math.floor(rng()*3);const t=shuf(CORD,rng).slice(0,nt);return buildVC('con',t,{rng:rng,kinds:Math.min(8,5+Math.floor(k/4)),lab:'m',total:40+Math.round(lev*1.2),secs:secs,title:title,conf:true})}
 if(mode==='f31'){const f=pick(FAM,rng);return buildF31(f,{rng:rng,total:40+Math.round(lev*1.2),secs:secs,title:title,nd:3+Math.floor(rng()*3)})}
 const nn=8+Math.floor(rng()*23);const K=Math.min(10,6+Math.floor(k/3));const w=pickWords(nn,rng,K);
 return buildF32(w,{rng:rng,goal:Math.min(40,20+lev),secs:secs,title:title})}
/* ---------- modos criados no Studio do professor ---------- */
function customSpec(mode,c){
 const rng=mulberry(Date.now()&0xffffff),secs=Math.max(5,Math.min(15,c.mins||8))*60,title=c.title||'Modo do professor';
 const size=[4,5,6,7].indexOf(+c.size)>=0?+c.size:6;
 const d=c.nd===undefined?3:Math.max(0,Math.min(8,+c.nd));
 if(mode==='vog'||mode==='con'){const t=(c.targets&&c.targets.length?c.targets:[mode==='vog'?'a':'f']).map(x=>x.toLowerCase());
  return buildVC(mode,t,{rng:rng,kinds:Math.min(9,Math.max(3,t.length+d)),lab:c.lab||'u',total:c.goal||15,secs:secs,title:title,dtype:c.dtype||'both',size:size,conf:true})}
 if(mode==='f31'){const toks=String(c.family||'p').trim().split(/[\s,;]+/).filter(Boolean);let syls=null,fams=null,fam=toks[0]||'p';
  if(toks.every(x=>FAM.indexOf(x.toUpperCase())>=0)){fams=toks.map(x=>x.toUpperCase());syls=[];fams.forEach(f=>famSyl(f).forEach(x=>syls.push(x)));fam=fams.join(' + ')}
  else{syls=toks.map(x=>x.toLowerCase()).slice(0,8);fam=syls.join(' ').toUpperCase()}
  return buildF31(fam,{rng:rng,syls:syls,fams:fams,famName:fam,total:c.goal||16,secs:secs,title:title,nd:d,size:size})}
 let words=(c.words||[]).map(x=>{const s=String(x).trim().toLowerCase().split('-').filter(Boolean);return{w:s.join(''),s:s}}).filter(x=>x.s.length>=2);
 if(!words.length)words=pickWords(12,rng,6);
 return buildF32(words,{rng:rng,strict:!!c.strict,goal:c.goal||words.length,secs:secs,title:title,nd:d,noDistract:false,size:size})}

/* ===== motor do tabuleiro ===== */
let G=null;
let RW=6,CL=6;
function lineWords(cells){
 const out=[];let i=0;const n=cells.length;
 while(i<n){let hit=0;
  for(let L=Math.min(5,n-i);L>=2;L--){let s='';for(let k=0;k<L;k++){const t=cells[i+k].t;if(!t){s='';break}s+=t.key}
   if(s&&okWord(s)){out.push({cells:cells.slice(i,i+L),word:s});hit=L;break}}
  i+=hit||1}
 return out}
function okWord(s){if(s.length<3)return false;if(G.wset.has(s))return true;if(G.spec.strict||s.length<4)return false;return DSET.has(s)||CSET.has(s)}
function findMatches(){
 const g=G.grid,runs=[];
 if(G.spec.kind==='same'){
  for(let r=0;r<RW;r++){let c=0;while(c<CL){let e=c;while(e+1<CL&&g[r][e+1]&&g[r][c]&&g[r][e+1].key===g[r][c].key)e++;if(g[r][c]&&e-c>=2){const cs=[];for(let k=c;k<=e;k++)cs.push([r,k]);runs.push({cells:cs,key:g[r][c].key,label:g[r][c].label})}c=e+1}}
  for(let c=0;c<CL;c++){let r=0;while(r<RW){let e=r;while(e+1<RW&&g[e+1][c]&&g[r][c]&&g[e+1][c].key===g[r][c].key)e++;if(g[r][c]&&e-r>=2){const cs=[];for(let k=r;k<=e;k++)cs.push([k,c]);runs.push({cells:cs,key:g[r][c].key,label:g[r][c].label})}r=e+1}}
  return runs}
 for(let r=0;r<RW;r++){const cs=[];for(let c=0;c<CL;c++)cs.push({r:r,c:c,t:g[r][c]});lineWords(cs).forEach(x=>runs.push({cells:x.cells.map(q=>[q.r,q.c]),word:x.word,sylls:x.cells.map(q=>q.t.label)}))}
 for(let c=0;c<CL;c++){const cs=[];for(let r=0;r<RW;r++)cs.push({r:r,c:c,t:g[r][c]});lineWords(cs).forEach(x=>runs.push({cells:x.cells.map(q=>[q.r,q.c]),word:x.word,sylls:x.cells.map(q=>q.t.label)}))}
 return runs}
function symPick(){
 const S=G.spec.symbols;let w=S.map(s=>s.w);
 if(G.spec.kind==='words'){const need=neededSyl();w=S.map(s=>s.w*(need[s.key]?(G.spec.strict?4:2):1))}
 let tot=0;w.forEach(x=>tot+=x);let r=Math.random()*tot;for(let i=0;i<S.length;i++){r-=w[i];if(r<=0)return S[i]}return S[0]}
function neededSyl(){
 const have={};G.grid.forEach(row=>row.forEach(t=>{if(t)have[t.key]=(have[t.key]||0)+1}));
 const need={};let cnt=0;
 for(const w of G.spec.words){if(w.done)continue;if(cnt++>=6)break;const tmp=Object.assign({},have);w.s.forEach(k=>{if(tmp[k]>0)tmp[k]--;else need[k]=1})}
 return need}
function mkTile(sym){
 const li=Math.floor(Math.random()*sym.labels.length);const label=sym.labels[li];
 const cc=PAL[sym.cols[li]];
 const e=document.createElement('div');e.className='t'+(sym.syl||G.spec.mode==='f31'?' syl l'+Math.min(4,label.length):'');
 e.style.setProperty('--t1',cc[0]);e.style.setProperty('--t2',cc[1]);
 const i=document.createElement('div');i.className='ti';i.textContent=label;e.appendChild(i);
 G.board.appendChild(e);return{key:sym.key,label:label,sym:sym,el:e,r:0,c:0}}
function place(t,r,c){t.r=r;t.c=c;t.el.style.transform='translate('+c*100+'%,'+r*100+'%)'}
function renderAll(){G.grid.forEach((row,r)=>row.forEach((t,c)=>{if(t)place(t,r,c)}))}
function makesRun(r,c,key){const g=G.grid;const at=(a,b)=>g[a]&&g[a][b]?g[a][b].key:null;
 if(at(r,c-1)===key&&at(r,c-2)===key)return true;if(at(r-1,c)===key&&at(r-2,c)===key)return true;
 if(at(r,c+1)===key&&at(r,c+2)===key)return true;if(at(r+1,c)===key&&at(r+2,c)===key)return true;return false}
function swapG(r1,c1,r2,c2){const g=G.grid;const a=g[r1][c1];g[r1][c1]=g[r2][c2];g[r2][c2]=a}
function fillInitial(){
 G.board.innerHTML='';G.grid=[];for(let r=0;r<RW;r++)G.grid.push(new Array(CL).fill(null));
 const cells=[];for(let r=0;r<RW;r++)for(let c=0;c<CL;c++)cells.push([r,c]);
 const sp=G.spec;let seeds=[];
 if(sp.kind==='words'){let cnt=0;for(const w of sp.words){if(cnt+w.s.length>Math.floor(RW*CL*.7))break;w.s.forEach(k=>seeds.push(k));cnt+=w.s.length}seeds=shuf(seeds,Math.random)}
 const order=shuf(cells,Math.random);
 order.forEach(([r,c],i)=>{let sym;
  if(i<seeds.length)sym=sp.symbols.find(s=>s.key===seeds[i]);else sym=symPick();
  if(sp.kind==='same'){let guard=0;while(guard++<30&&makesRun(r,c,sym.key))sym=symPick()}
  const t=mkTile(sym);G.grid[r][c]=t;place(t,r,c)});
 if(sp.kind==='words'){
  for(let g=0;g<1500;g++){const m=findMatches();if(!m.length)break;const cs=m[0].cells;const q=cs[Math.floor(Math.random()*cs.length)];
   if(g<300)swapG(q[0],q[1],Math.floor(Math.random()*RW),Math.floor(Math.random()*CL));
   else{const o=G.grid[q[0]][q[1]];o.el.remove();const S=sp.symbols;const t=mkTile(S[Math.floor(Math.random()*S.length)]);G.grid[q[0]][q[1]]=t;place(t,q[0],q[1])}}}
 renderAll()}
function findMove(){const list=[];
 for(let r=0;r<RW;r++)for(let c=0;c<CL;c++){if(c+1<CL)list.push([r,c,r,c+1]);if(r+1<RW)list.push([r,c,r+1,c])}
 for(const q of shuf(list,Math.random)){swapG(q[0],q[1],q[2],q[3]);const m=findMatches().length;swapG(q[0],q[1],q[2],q[3]);if(m)return[[q[0],q[1]],[q[2],q[3]]]}
 return null}
function shuffleBoard(){toast('Embaralhando…');
 for(let k=0;k<80;k++){const ts=[];G.grid.forEach(row=>row.forEach(t=>ts.push(t)));const o=shuf(ts,Math.random);let i=0;for(let r=0;r<RW;r++)for(let c=0;c<CL;c++)G.grid[r][c]=o[i++];
  if(!findMatches().length&&findMove())break}
 renderAll()}
function clearHint(){if(!G||!G.board)return;G.board.querySelectorAll('.hint,.sel').forEach(e=>e.classList.remove('hint','sel'));G.sel=null}
function showHint(){if(!G||G.busy||G.over||G.paused)return;clearHint();const m=findMove();if(!m)return;m.forEach(q=>G.grid[q[0]][q[1]].el.classList.add('hint'))}
/* ---------- partida ---------- */
function startGame(spec,meta,root){
 buildDict();document.body.classList.remove('cred');RW=spec.rows||6;CL=spec.cols||6;
 if(G)stopGame();
 G={spec:spec,meta:meta,left:spec.secs,total:spec.secs,progress:{},formed:0,busy:false,over:false,paused:false,sel:null,score:0,idle:0,grid:[],board:null,drag:null,wset:new Set(),found:{},last:performance.now(),lastSec:-1};
 if(spec.kind==='words')spec.words.forEach(w=>G.wset.add(w.w));
 spec.goals.forEach(g=>G.progress[g.key]=0);
 root.innerHTML=gameHTML(spec,meta);
 G.board=$('#board',root);G.root=root;
 root.classList.toggle('lc-upper',DB.set.letters==='upper');
 fillInitial();
 if(!findMove())shuffleBoard();
 bindBoard();updateGoal();tickTimer();fitBoard();setTimeout(fitBoard,60);
 G.iv=setInterval(loopTick,200);
 document.addEventListener('visibilitychange',visPause);document.body.classList.add('playing')}
function fitBoard(){const g=$('#game'),st=$('.stage');if(!g||!st)return;const r=st.getBoundingClientRect();const bs=Math.floor(Math.max(120,Math.min(r.width-4,r.height-4,680)));g.style.setProperty('--bs',bs+'px')}
window.addEventListener('resize',()=>{try{fitBoard()}catch(e){}});window.addEventListener('orientationchange',()=>setTimeout(fitBoard,200));
function gameHTML(sp,meta){
 const chips=sp.kind==='words'&&sp.words.length<=14?(sp.strict?'':'<div style="font-size:12px;color:var(--mut);margin-top:8px">Palavras do dia (⭐ bônus) — qualquer palavra do dicionário também vale!</div>')+'<div class="wchips" id="wch">'+sp.words.map((w,i)=>'<span class="chip" data-i="'+i+'">'+esc(w.disp)+'</span>').join('')+'</div>':'';
 return '<div id="game" style="--cols:'+CL+';--rows:'+RW+'"><div class="ghead"><button class="icon" data-act="quit" aria-label="Sair">✕</button><div class="gwho"><b>'+esc(MODES[sp.mode].name)+'</b><span>'+esc(sp.title)+'</span></div><button class="icon" data-act="pause" aria-label="Pausar">⏸</button><div id="timer">0:00</div></div>'
 +'<div class="goal"><div class="gtxt"><span id="gtext">'+esc(sp.sub)+'</span><em id="gnum"></em></div><div class="gitems" id="gitems"></div>'+chips+'</div>'
 +'<div class="stage"><div class="board" id="board" style="--cols:'+CL+';--rows:'+RW+'"></div></div>'
 +'<div class="gbar"><button class="btn" data-act="hint">💡 Dica</button><div class="sbTrack"><i id="tbar"></i></div><button class="btn" data-act="speakgoal">🔊</button></div></div>'}
function fmt(s){s=Math.max(0,Math.ceil(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function tickTimer(){const t=$('#timer');if(!t||!G)return;t.textContent=fmt(G.left);t.classList.toggle('warn',G.left<=30);const b=$('#tbar');if(b)b.style.width=Math.max(0,G.left/G.total*100)+'%'}
function loopTick(){if(!G||G.over)return;const now=performance.now();const dt=Math.min(1,(now-G.last)/1000);G.last=now;if(G.paused)return;
 G.left-=dt*(window.MDL_TIME||1);const ls=Math.floor(G.left);if(G.left<=30&&G.left>0&&ls!==G.lastSec){G.lastSec=ls;if(ls%5===0)Snd.tick()}
 G.idle+=dt;if(G.idle>9&&!G.busy&&!G.hinted){G.hinted=true;showHint()}
 tickTimer();if(G.left<=0){G.left=0;tickTimer();finish(false)}}
function visPause(){if(document.hidden&&G&&!G.over&&!G.paused)pauseGame(true)}
function pauseGame(on){if(!G||G.over)return;G.paused=on;if(on)UI.pauseModal()}
function stopGame(){document.body.classList.remove('playing');if(!G)return;clearInterval(G.iv);document.removeEventListener('visibilitychange',visPause);G.over=true}
/* ---------- entrada ---------- */
function cellAt(e){const b=G.board.getBoundingClientRect();const x=e.clientX-b.left,y=e.clientY-b.top;if(x<0||y<0||x>=b.width||y>=b.height)return null;return{r:Math.floor(y/(b.height/RW)),c:Math.floor(x/(b.width/CL)),cw:b.width/CL}}
function bindBoard(){const b=G.board;
 b.addEventListener('pointerdown',e=>{if(G.busy||G.over||G.paused)return;const p=cellAt(e);if(!p)return;G.drag={p:p,x:e.clientX,y:e.clientY,done:false};G.idle=0;G.hinted=false;try{b.setPointerCapture(e.pointerId)}catch(_){}});
 b.addEventListener('pointermove',e=>{const d=G.drag;if(!d||d.done)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.max(Math.abs(dx),Math.abs(dy))<d.p.cw*.4)return;d.done=true;let r=d.p.r,c=d.p.c;if(Math.abs(dx)>Math.abs(dy))c+=dx>0?1:-1;else r+=dy>0?1:-1;if(r<0||c<0||r>=RW||c>=CL)return;clearHint();doSwap(d.p.r,d.p.c,r,c)});
 b.addEventListener('pointerup',()=>{const d=G.drag;G.drag=null;if(d&&!d.done)tapCell(d.p.r,d.p.c)});
 b.addEventListener('pointercancel',()=>{G.drag=null})}
function tapCell(r,c){if(G.busy||G.over||G.paused)return;const s=G.sel;if(!s||s[0]!==r||s[1]!==c)speakTile(G.grid[r][c].label);
 if(!s){clearHint();G.sel=[r,c];G.grid[r][c].el.classList.add('sel');return}
 if(s[0]===r&&s[1]===c){clearHint();return}
 if(Math.abs(s[0]-r)+Math.abs(s[1]-c)===1){const a=s;clearHint();doSwap(a[0],a[1],r,c)}
 else{clearHint();G.sel=[r,c];G.grid[r][c].el.classList.add('sel')}}
async function doSwap(r1,c1,r2,c2){
 if(!G||G.busy||G.over)return;G.busy=true;clearHint();
 swapG(r1,c1,r2,c2);place(G.grid[r1][c1],r1,c1);place(G.grid[r2][c2],r2,c2);await wait(230);
 if(!G||G.over){return}
 if(!findMatches().length){swapG(r1,c1,r2,c2);const a=G.grid[r1][c1],b=G.grid[r2][c2];place(a,r1,c1);place(b,r2,c2);a.el.classList.add('nope');b.el.classList.add('nope');Snd.bad();await wait(260);a.el.classList.remove('nope');b.el.classList.remove('nope');G.busy=false;return}
 await cascade();
 if(!G||G.over)return;
 G.busy=false;G.idle=0;G.hinted=false;
 if(!findMove())shuffleBoard()}
async function cascade(){
 let chain=0;
 for(;;){const runs=findMatches();if(!runs.length)break;chain++;
  const set=new Map();runs.forEach(rn=>rn.cells.forEach(q=>set.set(q[0]*10+q[1],q)));
  applyGoal(runs,set,chain);
  set.forEach(q=>G.grid[q[0]][q[1]].el.classList.add('pop'));
  Snd.match(chain);await wait(270);if(!G||G.over)return;
  set.forEach(q=>{G.grid[q[0]][q[1]].el.remove();G.grid[q[0]][q[1]]=null});
  const fresh=[];
  for(let c=0;c<CL;c++){let w=RW-1;for(let r=RW-1;r>=0;r--){const t=G.grid[r][c];if(t){if(r!==w){G.grid[w][c]=t;G.grid[r][c]=null;place(t,w,c)}w--}}
   for(let r=w;r>=0;r--){const t=mkTile(symPick());fresh.push(t);t.el.classList.add('spawn');place(t,r-w-2,c);G.grid[r][c]=t;(function(t,r,c){requestAnimationFrame(()=>requestAnimationFrame(()=>{t.el.classList.remove('spawn');place(t,r,c)}))})(t,r,c)}}
  antiChain(fresh);
  await wait(340);if(!G||G.over)return;updateGoal();
  if(goalDone()){finish(true);return}}
}
function retile(t,sym){const li=Math.floor(Math.random()*sym.labels.length);t.key=sym.key;t.sym=sym;t.label=sym.labels[li];const cc=PAL[sym.cols[li]];t.el.style.setProperty('--t1',cc[0]);t.el.style.setProperty('--t2',cc[1]);t.el.firstChild.textContent=t.label;t.el.classList.remove('l1','l2','l3','l4');if(sym.syl||G.spec.mode==='f31')t.el.classList.add('l'+Math.min(4,t.label.length))}
function antiChain(fresh){/* evita que as peças novas formem combinações sozinhas: o aluno precisa jogar */
 for(let k=0;k<60;k++){const m=findMatches();if(!m.length)return;let done=false;
  for(const rn of m){let t=rn.cells.map(q=>G.grid[q[0]][q[1]]).find(x=>fresh.indexOf(x)>=0);if(!t&&G.spec.kind==='words'){t=G.grid[rn.cells[0][0]][rn.cells[0][1]];fresh.push(t)}if(t){const S=G.spec.symbols.filter(s=>s.key!==t.key);if(S.length){retile(t,S[Math.floor(Math.random()*S.length)]);done=true;break}}}
  if(!done)return}}
function applyGoal(runs,set,chain){
 const sp=G.spec;
 if(sp.kind==='same'){let pts=0;
  set.forEach(q=>{const t=G.grid[q[0]][q[1]];if(t.sym.cat){pts+=10*chain;if(G.progress[t.key]!==undefined)G.progress[t.key]++;else if(G.progress['*']!==undefined&&t.sym.target)G.progress['*']++;FX.sparks(t)}});
  G.score+=pts;
  const rn=runs.find(r=>G.grid[r.cells[0][0]][r.cells[0][1]].sym.cat);
  if(rn){speakTile(rn.label);wtoast(rn.label+(chain>1?' ✨':''));FX.float(rn.cells[0],'+'+(rn.cells.length*10*chain))}
  return}
 G.score+=set.size*10*chain;set.forEach(q=>FX.sparks(G.grid[q[0]][q[1]]));
 const seen={};runs.forEach(rn=>{if(seen[rn.word])return;seen[rn.word]=1;if(!G.found[rn.word]){G.found[rn.word]=1;G.formed++}const w=sp.words.find(x=>x.w===rn.word&&!x.done);if(w){w.done=true;G.score+=100}
  wtoast(rn.sylls.join('·').toLowerCase());speak(rn.sylls.join(''))})}
function goalDone(){const sp=G.spec;if(sp.kind==='words'){if(sp.strict)return sp.words.every(w=>w.done);return G.formed>=sp.goalN}return sp.goals.every(g=>G.progress[g.key]>=g.n)}
function updateGoal(){const sp=G.spec,gi=$('#gitems');if(!gi)return;const gn=$('#gnum');if(gn)gn.textContent='⭐ '+G.score;
 if(sp.kind==='words'){const done=sp.strict?sp.words.filter(w=>w.done).length:G.formed,tot=sp.strict?sp.words.length:sp.goalN;
  gi.innerHTML='<div class="gi'+(done>=tot?' done':'')+'"><small><span>Palavras</span><b>'+Math.min(done,tot)+'/'+tot+'</b></small><div class="bar"><i style="width:'+Math.min(100,done/tot*100)+'%"></i></div></div>';
  sp.words.forEach((w,i)=>{const c=$('#wch [data-i="'+i+'"]');if(c)c.classList.toggle('ok',w.done)});return}
 gi.innerHTML=sp.goals.map(g=>{const v=Math.min(G.progress[g.key],g.n);return'<div class="gi'+(v>=g.n?' done':'')+'"><small><span>'+esc(g.label)+'</span><b>'+v+'/'+g.n+'</b></small><div class="bar"><i style="width:'+v/g.n*100+'%"></i></div></div>'}).join('')}
function finish(win){if(!G||G.over)return;stopGame();const f=G.left/G.total;const st=win?(f>=.35?3:f>=.12?2:1):0;
 if(win){Snd.win();wtoast('Parabéns!')}else Snd.lose();
 const res={win:win,stars:st,left:G.left,total:G.total,formed:G.formed,progress:G.progress,spec:G.spec,meta:G.meta,score:G.score};
 setTimeout(()=>UI.result(res),win?900:300)}

/* ===== interface ===== */
const UI={};
const app=()=>$('#app');
function modal(html,cls){const m=document.createElement('div');m.className='modal';m.innerHTML='<div class="mcard '+(cls||'')+'">'+html+'</div>';document.body.appendChild(m);return m}
function closeModals(){document.querySelectorAll('.modal').forEach(m=>m.remove())}
function closeTop(){const a=document.querySelectorAll('.modal');if(a.length)a[a.length-1].remove()}
function starStr(n){return'★'.repeat(n)+'☆'.repeat(3-n)}
function modeStars(mode){let s=0,d=0;for(let i=1;i<=30;i++){const x=stars(mode,i);s+=x;if(x)d++}return{s:s,d:d}}
function unlocked(mode,n){return DB.set.unlock||n===1||stars(mode,n-1)>0}
function ini(n){return esc((n||'?').trim().charAt(0).toUpperCase())}
function rainbow(t){let i=0;return t.split('').map(ch=>ch===' '?'<span class="sp0"></span>':'<span style="--i:'+(i)+';--c:'+PAL[(i++)%PAL.length][0]+'">'+esc(ch)+'</span>').join('')}
const FSOK=!!(document.fullscreenEnabled||document.webkitFullscreenEnabled);
function toggleFS(){try{const d=document,e=d.documentElement;if(d.fullscreenElement||d.webkitFullscreenElement){(d.exitFullscreen||d.webkitExitFullscreen).call(d)}else{(e.requestFullscreen||e.webkitRequestFullscreen).call(e)}}catch(x){}}
const fsBtn=()=>FSOK?'<button class="icon" data-act="fs" aria-label="Tela cheia">⛶</button>':'';
UI.welcome=function(){document.body.classList.add('cred');stopGame();closeModals();
 app().innerHTML='<div class="scr welcome"><div class="wrap"><div class="top" style="justify-content:flex-end">'+fsBtn()+'<button class="icon" data-act="settings" aria-label="Configurações">⚙️</button></div>'
 +'<div class="mascots">'+'AEIOU'.split('').map((c,i)=>'<div class="mt" style="--i:'+i+';--t1:'+PAL[i][0]+';--t2:'+PAL[i][1]+'"><span>'+c+'</span></div>').join('')+'</div>'
 +'<h1 class="rainbow big1">'+rainbow('Magia')+'</h1><h1 class="rainbow big2">'+rainbow('das Letras')+'</h1><p class="sub">Vamos brincar com as letras e as palavras?</p>'
 +'<button class="btn primary jogar" data-act="playbtn">▶ JOGAR</button></div></div>'};
/* ---------- tela: jogadores ---------- */
UI.players=function(first){document.body.classList.add('cred');stopGame();closeModals();const names=Object.keys(DB.players);
 app().innerHTML='<div class="scr"><div class="wrap"><div class="top"><button class="icon" data-act="welcome" aria-label="Voltar">←</button></div><h1 class="rainbow">'+rainbow('Quem vai jogar?')+'</h1><p class="sub">Escolha seu nome ou digite um novo</p>'
 +(names.length?'<div class="plist">'+names.map(n=>'<div class="pitem"><button class="btn" data-act="pick" data-n="'+esc(n)+'">'+esc(n)+'</button><button class="icon" data-act="delp" data-n="'+esc(n)+'" aria-label="Apagar">🗑</button></div>').join('')+'</div>':'')
 +'<div class="tbox"><label class="fld" style="margin-top:0"><span>Novo jogador</span><input type="text" id="newName" maxlength="20" placeholder="Digite seu nome" autocomplete="off"></label><button class="btn primary" data-act="addp" style="margin-top:12px">Jogar</button></div></div></div>'};
/* ---------- tela: início ---------- */
UI.inStudio=false;
UI.home=function(){UI.inStudio=false;document.body.classList.add('cred');stopGame();closeModals();const n=DB.player||'?';
 const card=(m,extra)=>{const M=MODES[m],p=modeStars(m);return'<button class="modeCard" style="--mc:'+M.color+'" data-act="mode" data-m="'+m+'"><div class="mIco'+(M.ico.length>2?' sm':'')+'">'+esc(M.ico)+'</div><b>'+esc(M.name)+'</b><span>'+esc(M.desc)+'</span><div class="prog">★ '+p.s+' · '+p.d+'/30 níveis</div></button>'};
 const fcard=m=>{const M=MODES[m],p=modeStars(m);return'<button class="modeCard" style="--mc:'+M.color+'" data-act="mode" data-m="'+m+'"><div class="mIco sm">'+esc(M.ico)+'</div><b>'+(m==='f31'?'3.1 ':'3.2 ')+esc(M.name)+'</b><span>'+esc(M.desc)+'</span><div class="prog">★ '+p.s+' · '+p.d+'/30 níveis</div></button>'};
 app().innerHTML='<div class="scr"><div class="wrap"><div class="top"><button class="pill" data-act="players"><span class="av">'+ini(n)+'</span>'+esc(n)+'</button>'+fsBtn()+'<button class="icon" data-act="settings" aria-label="Configurações">⚙️</button></div>'
 +'<h1 class="rainbow">'+rainbow('Magia das Letras')+'</h1><p class="sub">Escolha como quer brincar</p><div class="cards">'
 +card('vog')+card('con')
 +'<div class="famBox"><div class="famHead"><div class="mIco sm" style="background:#a78bfa">BA</div><div><b>Modo Família Silábica</b><span>Aprenda as sílabas e forme palavras</span></div></div>'+fcard('f31')+fcard('f32')+'</div><button class="modeCard" style="--mc:#34d399" data-act="studio"><div class="mIco sm">🎛</div><b>Studio do Professor</b><span>Crie modos e regras para a aula de hoje</span></button></div>'+homeList()+'</div></div>'};
function homeList(){const rows=[];MKEYS.forEach(m=>{(DB.custom[m]||[]).forEach((c,i)=>rows.push([m,c,'own',i]));((window.CLASSCH&&CLASSCH[m])||[]).forEach((c,i)=>rows.push([m,c,'cls',i]))});
 if(!rows.length)return'';return'<div class="sect">👩‍🏫 Modos do professor</div><div class="tbox">'+rows.map(r=>'<div class="citem"><div class="ct"><b>'+esc(r[1].title||'Modo')+(r[2]==='cls'?'<span class="tag">turma</span>':'')+'</b><small>'+esc(MODES[r[0]].name+' · '+customSummary(r[0],r[1]))+'</small></div><button class="icon" data-act="hplay" data-m="'+r[0]+'" data-s="'+r[2]+'" data-i="'+r[3]+'" aria-label="Jogar">▶</button></div>').join('')+'</div>'}
/* ---------- tela: trilha de um modo ---------- */
UI.mode=function(m){UI.inStudio=false;document.body.classList.remove('cred');stopGame();closeModals();UI.cur=m;const M=MODES[m];const p=modeStars(m);
 let rows='';for(let r=0;r<6;r++){let nodes='';const idx=[];for(let k=0;k<5;k++)idx.push(r*5+k+1);if(r%2)idx.reverse();
  idx.forEach(n=>{const s=stars(m,n),ok=unlocked(m,n);const cur=ok&&!s&&(n===1||stars(m,n-1)>0||DB.set.unlock&&false);
   nodes+='<button class="node'+(s?' done':cur?' cur':!ok?' lock':'')+'" data-act="lvl" data-n="'+n+'" '+(ok?'':'disabled')+'>'+(ok?n:'🔒')+(s?'<i>'+'★'.repeat(s)+'</i>':'')+'</button>'});
  rows+='<div class="trow">'+nodes+'</div>'}
 const infOk=DB.set.unlock||stars(m,30)>0;const infN=(me().inf[m]||0);
 const custom=customList(m);
 app().innerHTML='<div class="scr" style="--mc:'+M.color+'"><div class="wrap"><div class="top"><button class="icon" data-act="home" aria-label="Voltar">←</button><div style="text-align:center;flex:1"><b style="font-size:20px">'+esc(M.name)+'</b><div class="sub" style="margin:0">★ '+p.s+' · '+p.d+'/30</div></div>'+fsBtn()+'<button class="icon" data-act="settings">⚙️</button></div>'
 +'<div class="trail">'+rows+'</div>'
 +'<button class="modeCard infCard" style="--mc:'+M.color+';'+(infOk?'':'opacity:.5')+'" data-act="inf" '+(infOk?'':'disabled')+'><div class="mIco">∞</div><b>Modo Infinito</b><span>'+(infOk?'Desafios novos a cada partida':'Conclua o nível 30 para liberar')+'</span>'+(infN?'<div class="prog">Desafios vencidos: '+infN+'</div>':'')+'</button>'
 +'<div class="sect">👩‍🏫 Modos do professor</div><div class="tbox">'+custom+'<div class="row" style="margin-top:12px"><button class="btn" data-act="tnew">＋ Criar modo</button><button class="btn" data-act="studio">🎛 Studio</button></div></div></div></div>'};
function customList(m){const own=DB.custom[m]||[],cls=(window.CLASSCH&&CLASSCH[m])||[];let h='';
 const item=(c,src,i)=>'<div class="citem"><div class="ct"><b>'+esc(c.title||'Desafio')+(src==='cls'?'<span class="tag">turma</span>':'')+'</b><small>'+esc(customSummary(m,c))+'</small></div><button class="icon" data-act="cplay" data-s="'+src+'" data-i="'+i+'" aria-label="Jogar">▶</button>'+(src==='own'?'<button class="icon" data-act="cedit" data-i="'+i+'" aria-label="Editar">✎</button><button class="icon" data-act="cdel" data-i="'+i+'" aria-label="Apagar">🗑</button>':'')+'</div>';
 own.forEach((c,i)=>h+=item(c,'own',i));cls.forEach((c,i)=>h+=item(c,'cls',i));
 return h||'<p class="sub" style="margin:0">Nenhum modo criado ainda. Crie um para a aula de hoje!</p>'}
function customSummary(m,c){const t=(c.mins||8)+' min';
 if(m==='vog')return'Vogais '+(c.targets||[]).join(' ').toUpperCase()+' · '+t;
 if(m==='con')return'Letras '+(c.targets||[]).join(' ').toUpperCase()+' · '+t;
 if(m==='f31')return'Família '+String(c.family||'').toUpperCase()+' · '+t;
 return(c.words||[]).length+' palavras · '+t}
/* ---------- iniciar partidas ---------- */
UI.intro=function(spec,meta){
 const goal=spec.kind==='words'?(spec.strict?'Forme todas as '+spec.words.length+' palavras':'Forme '+spec.goalN+' palavras'):spec.goals.map(g=>g.n+'× '+g.label).join(' · ');
 const words=spec.kind==='words'&&spec.words.length<=12?'<div class="chips">'+spec.words.map(w=>'<span class="chip">'+esc(w.disp)+'</span>').join('')+'</div>':'';
 const m=modal('<div class="big">'+esc(MODES[spec.mode].ico)+'</div><h2>'+esc(spec.title)+'</h2><p>'+esc(MODES[spec.mode].how)+'</p><div class="chip" style="display:inline-block;margin-bottom:6px">🎯 '+esc(spec.kind==='words'?goal:spec.sub)+'</div>'+(spec.kind==='words'?'':'<div style="color:var(--mut);font-size:14px;margin-bottom:6px">'+esc(goal)+'</div>')+words+'<div style="color:#fde68a;font-weight:600;margin:8px 0 16px">⏱ '+Math.round(spec.secs/60)+' minutos</div><button class="btn primary" data-act="go">Vamos lá!</button><button class="btn" data-act="cancel">Voltar</button>');
 UI._pend={spec:spec,meta:meta}};
UI.begin=function(){const p=UI._pend;if(!p)return;closeModals();startGame(p.spec,p.meta,app());speak(p.spec.kind==='words'?'Forme palavras':'Vamos jogar')};
UI.play=function(mode,meta){let spec;
 buildDict();
 if(meta.kind==='lvl')spec=levelSpec(mode,meta.n);
 else if(meta.kind==='inf')spec=infSpec(mode,meta.n);
 else spec=customSpec(mode,meta.c);
 if(spec.kind==='words'&&spec.words.length<1){toast('Esse desafio precisa de palavras com 2 ou mais sílabas.');return}
 UI.intro(spec,meta)};
UI.pauseModal=function(){modal('<div class="big">⏸</div><h2>Jogo pausado</h2><p>O tempo está parado.</p><button class="btn primary" data-act="resume">Continuar</button><button class="btn" data-act="restart">Reiniciar fase</button><button class="btn danger" data-act="leave">Sair</button>')};
UI.result=function(r){closeModals();const mode=r.spec.mode,meta=r.meta;let h='';
 if(r.win){
  if(meta.kind==='lvl')setStars(mode,meta.n,r.stars);
  if(meta.kind==='inf'){const p=me();p.inf[mode]=Math.max(p.inf[mode]||0,meta.n);save()}
  const lastLvl=meta.kind==='lvl'&&meta.n===30;
  const wl=r.spec.kind==='words'?'<div class="chips">'+r.spec.words.filter(w=>w.done).map(w=>'<span class="chip ok">'+esc(w.disp)+'</span>').join('')+'</div>':'';
  h='<div class="big">🎉</div><h2>Muito bem!</h2><div class="stars">'+[1,2,3].map(i=>'<b class="'+(i<=r.stars?'on':'')+'">★</b>').join('')+'</div><p>Sobraram '+fmt(r.left)+' de '+fmt(r.total)+(r.score?' · '+r.score+' pontos':'')+'.'+(lastLvl?' Modo Infinito liberado! ∞':'')+'</p>'+wl
  +(meta.kind==='lvl'&&meta.n<30?'<button class="btn primary" data-act="next">Próximo nível</button>':meta.kind==='lvl'?'<button class="btn primary" data-act="next">Ir para o Modo Infinito ∞</button>':meta.kind==='inf'?'<button class="btn primary" data-act="next">Próximo desafio ∞</button>':'')}
 else{const pr=r.spec.kind==='words'?'Palavras: '+Math.min(r.spec.strict?r.spec.words.filter(w=>w.done).length:r.formed,r.spec.strict?r.spec.words.length:r.spec.goalN)+'/'+(r.spec.strict?r.spec.words.length:r.spec.goalN):r.spec.goals.map(g=>g.label+' '+Math.min(r.progress[g.key]||0,g.n)+'/'+g.n).join(' · ');
  h='<div class="big">⏰</div><h2>O tempo acabou!</h2><p>Você quase conseguiu.<br>'+esc(pr)+'</p>'}
 h+='<button class="btn'+(r.win?'':' primary')+'" data-act="restart">Jogar de novo</button><button class="btn" data-act="leave">Voltar ao mapa</button>';
 UI._last=r;modal(h);if(r.win)FX.confetti()};
/* ---------- Studio do Professor ---------- */
UI.studio=function(){UI.inStudio=true;closeModals();document.body.classList.remove('cred');stopGame();const s=DB.set;
 const rows=[];MKEYS.forEach(m=>{(DB.custom[m]||[]).forEach((c,i)=>rows.push([m,c,'own',i]));((window.CLASSCH&&CLASSCH[m])||[]).forEach((c,i)=>rows.push([m,c,'cls',i]))});
 const list=rows.length?rows.map(r=>'<div class="citem"><div class="ct"><b>'+esc(r[1].title||'Modo')+(r[2]==='cls'?'<span class="tag">turma</span>':'')+'</b><small>'+esc(MODES[r[0]].name+' · '+customSummary(r[0],r[1]))+'</small></div><button class="icon" data-act="sfplay" data-m="'+r[0]+'" data-s="'+r[2]+'" data-i="'+r[3]+'" aria-label="Jogar">▶</button>'+(r[2]==='own'?'<button class="icon" data-act="sfedit" data-m="'+r[0]+'" data-i="'+r[3]+'" aria-label="Editar">✎</button><button class="icon" data-act="sfdel" data-m="'+r[0]+'" data-i="'+r[3]+'" aria-label="Apagar">🗑</button>':'')+'</div>').join(''):'<p class="sub" style="margin:0">Nenhum modo ainda. Escolha um tipo acima para criar o primeiro.</p>';
 const nc=m=>{const M=MODES[m];return'<button class="modeCard" style="--mc:'+M.color+'" data-act="snew" data-m="'+m+'"><div class="mIco'+(M.ico.length>2?' sm':'')+'">'+esc(M.ico)+'</div><b>＋ '+esc(M.name)+'</b><span>'+esc(M.desc)+'</span></button>'};
 app().innerHTML='<div class="scr"><div class="wrap"><div class="top"><button class="icon" data-act="home" aria-label="Voltar">←</button><div style="text-align:center;flex:1"><b style="font-size:21px">🎛 Studio do Professor</b><div class="sub" style="margin:0">Crie as regras dos modos para a sua turma</div></div></div>'
 +'<div class="sect">1 · Criar um modo</div><div class="cards">'+nc('vog')+nc('con')+nc('f31')+nc('f32')+'</div>'
 +'<div class="sect">2 · Meus modos</div><div class="tbox">'+list+'</div>'
 +'<div class="sect">3 · Regras da turma</div><div class="tbox"><div class="sw"><span>Liberar todos os níveis</span><button class="'+(s.unlock?'on':'')+'" data-act="sunlock"></button></div><div class="sw"><span>Tipo de letra nas sílabas</span><div class="tg"><button class="'+(s.letters==='upper'?'on':'')+'" data-act="slc" data-v="upper">ABC</button><button class="'+(s.letters==='lower'?'on':'')+'" data-act="slc" data-v="lower">abc</button></div></div>'
 +'<div class="sw"><span>Sons do jogo</span><button class="'+(s.sound?'on':'')+'" data-act="ssw" data-k="sound"></button></div><div class="sw"><span>Ler letras e palavras em voz alta</span><button class="'+(s.voice?'on':'')+'" data-act="ssw" data-k="voice"></button></div></div>'
 +'<div class="sect">4 · Backup e senha</div><div class="tbox"><p class="sub" style="margin:0 0 10px;text-align:left">Para levar seus modos a outros aparelhos: exporte e coloque o arquivo <b>desafios.json</b> junto do jogo (GitHub Pages).</p><button class="btn" data-act="texp">⬇️ Exportar modos (desafios.json)</button><button class="btn" data-act="timp">⬆️ Importar modos</button><button class="btn" data-act="tpin">🔑 Trocar senha</button><button class="btn danger" data-act="treset">Apagar progresso do jogador atual</button><input type="file" id="impf" accept=".json,application/json" class="hidden"></div></div></div>'};
/* ---------- configurações ---------- */
UI.settings=function(){closeModals();const s=DB.set;
 const sw=(k,t)=>'<div class="sw"><span>'+t+'</span><button class="'+(s[k]?'on':'')+'" data-act="sw" data-k="'+k+'" aria-label="'+t+'"></button></div>';
 modal('<h2>⚙️ Configurações</h2>'+(FSOK?'<button class="btn" data-act="fs" style="margin-bottom:6px">⛶ Tela cheia (ligar/desligar)</button>':'')+sw('sound','Sons do jogo')+sw('voice','Ler letras e palavras em voz alta')
 +'<div class="sw"><span>Tipo de letra nas sílabas</span><div class="tg"><button class="'+(s.letters==='upper'?'on':'')+'" data-act="lc" data-v="upper">ABC</button><button class="'+(s.letters==='lower'?'on':'')+'" data-act="lc" data-v="lower">abc</button></div></div>'
 +'<div class="sw"><span>Liberar todos os níveis<br><small style="color:var(--mut)">'+(s.unlock?'Ligado':'Desligado')+' · exige senha</small></span><button class="'+(s.unlock?'on':'')+'" data-act="unlock"></button></div>'
 +'<div style="margin-top:14px"><button class="btn" data-act="players">👤 Trocar de jogador</button><button class="btn" data-act="studio">🎛 Studio do Professor</button><button class="btn" data-act="close">Fechar</button></div>','left')};
/* ---------- roteamento por cliques ---------- */
const A={
 welcome(){UI.welcome()},fs(){toggleFS()},playbtn(){speak('Vamos brincar');if(DB.player&&DB.players[DB.player])UI.home();else UI.players()},
 pick(d){DB.player=d.n;me();save();UI.home()},
 addp(){const i=$('#newName'),n=(i.value||'').trim();if(!n){i.classList.add('shake');setTimeout(()=>i.classList.remove('shake'),400);return}DB.player=n;me();save();UI.home()},
 delp(d){if(confirm('Apagar o jogador '+d.n+' e todo o progresso dele?')){delete DB.players[d.n];if(DB.player===d.n)DB.player=null;save();UI.players()}},
 players(){UI.players()},
 home(){UI.home()},settings(){UI.settings()},close(){closeTop()},cancel(){closeModals()},
 mode(d){UI.mode(d.m)},
 lvl(d){UI.play(UI.cur,{kind:'lvl',n:+d.n})},
 inf(){UI.play(UI.cur,{kind:'inf',n:(me().inf[UI.cur]||0)+1})},
 go(){UI.begin()},
 quit(){pauseGame(true)},pause(){pauseGame(true)},
 resume(){closeModals();if(G){G.paused=false;G.last=performance.now()}},
 restart(){closeModals();const m=G&&G.meta||UI._last&&UI._last.meta;const mode=G&&G.spec.mode||UI._last.spec.mode;stopGame();UI.cur=mode;UI.play(mode,m)},
 leave(){closeModals();const m=(G&&G.meta)||(UI._last&&UI._last.meta)||{};stopGame();if(m.from==='studio')UI.studio();else if(m.from==='home')UI.home();else UI.mode(UI.cur)},
 next(){const r=UI._last;closeModals();const m=r.meta;if(m.kind==='lvl'){if(m.n<30)UI.play(r.spec.mode,{kind:'lvl',n:m.n+1});else UI.play(r.spec.mode,{kind:'inf',n:1})}else UI.play(r.spec.mode,{kind:'inf',n:m.n+1})},
 hint(){if(G){G.idle=0;showHint()}},
 speakgoal(){if(!G)return;const s=G.spec;speak(s.kind==='words'?'Forme palavras juntando as sílabas':s.sub)},
 sw(d){DB.set[d.k]=!DB.set[d.k];save();UI.settings()},
 lc(d){DB.set.letters=d.v;save();UI.settings()},
 unlock(){Teach.pin(()=>{DB.set.unlock=!DB.set.unlock;save();UI.settings();if(UI.cur&&$('.trail'))UI.mode(UI.cur)})},
 tarea(){Teach.pin(()=>Teach.area())},
 tnew(){Teach.pin(()=>Teach.edit(UI.cur,-1))},
 cedit(d){Teach.pin(()=>Teach.edit(UI.cur,+d.i))},
 cdel(d){Teach.pin(()=>{if(confirm('Apagar este desafio?')){DB.custom[UI.cur].splice(+d.i,1);save();UI.mode(UI.cur)}})},
 cplay(d){const c=(d.s==='own'?DB.custom[UI.cur]:CLASSCH[UI.cur])[+d.i];UI.play(UI.cur,{kind:'custom',c:c,from:'mode'})},
 hplay(d){const c=(d.s==='own'?DB.custom[d.m]:CLASSCH[d.m])[+d.i];UI.cur=d.m;UI.play(d.m,{kind:'custom',c:c,from:'home'})},
 sfplay(d){const c=(d.s==='own'?DB.custom[d.m]:CLASSCH[d.m])[+d.i];UI.cur=d.m;UI.play(d.m,{kind:'custom',c:c,from:'studio'})},
 sfedit(d){UI.cur=d.m;Teach.edit(d.m,+d.i)},
 sfdel(d){if(confirm('Apagar este modo?')){DB.custom[d.m].splice(+d.i,1);save();UI.studio()}},
 snew(d){UI.cur=d.m;Teach.edit(d.m,-1)},
 studio(){Teach.pin(()=>UI.studio())},
 sunlock(){DB.set.unlock=!DB.set.unlock;save();UI.studio()},
 slc(d){DB.set.letters=d.v;save();UI.studio()},
 ssw(d){DB.set[d.k]=!DB.set[d.k];save();UI.studio()}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const f=A[b.dataset.act]||Teach.acts[b.dataset.act];if(f){e.preventDefault();f(b.dataset,b)}});

/* ===== efeitos visuais ===== */
const FX={};
FX.bg=function(){
 const cv=document.createElement('canvas');cv.id='bg';document.body.insertBefore(cv,document.body.firstChild);
 const x=cv.getContext('2d');let W=0,H=0,dpr=1;const reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
 const T='ABCDEFGHIJLMNOPQRSTUVXZ'.split('').concat(['BA','CA','LE','MO','TU','PI','NHA','ÃO','FA','VE','LI','GO']);
 let P=[],S=[];
 function init(){dpr=Math.min(2,window.devicePixelRatio||1);W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;cv.style.width=W+'px';cv.style.height=H+'px';
  const n=Math.max(14,Math.min(34,Math.round(W*H/32000)));P=[];for(let i=0;i<n;i++)P.push(mk(true));
  S=[];for(let i=0;i<50;i++)S.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.6+.4,p:Math.random()*6.28})}
 function mk(r){return{x:Math.random()*W,y:r?Math.random()*H:H+60,v:.25+Math.random()*.6,s:26+Math.random()*44,ch:T[Math.floor(Math.random()*T.length)],rot:(Math.random()-.5)*.8,vr:(Math.random()-.5)*.006,c:PAL[Math.floor(Math.random()*PAL.length)][0],a:.12+Math.random()*.16,ph:Math.random()*6.28}}
 let last=0;
 function frame(t){requestAnimationFrame(frame);if(document.hidden||t-last<33)return;last=t;
  x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,W,H);
  S.forEach(s=>{x.globalAlpha=.25+.5*Math.abs(Math.sin(t/900+s.p));x.fillStyle='#fff';x.beginPath();x.arc(s.x,s.y,s.r,0,6.28);x.fill()});
  x.textAlign='center';x.textBaseline='middle';
  P.forEach((p,i)=>{if(!reduce){p.y-=p.v;p.rot+=p.vr;}if(p.y<-70)P[i]=mk(false);
   x.save();x.translate(p.x+Math.sin(t/1500+p.ph)*14,p.y);x.rotate(p.rot);x.globalAlpha=p.a;x.fillStyle=p.c;x.shadowColor=p.c;x.shadowBlur=18;x.font='700 '+p.s+'px Fredoka,system-ui,sans-serif';x.fillText(p.ch,0,0);x.restore()})}
 init();addEventListener('resize',init);requestAnimationFrame(frame)};
FX.sparks=function(t){const b=G&&G.board;if(!b||!t)return;const cs=t.el.style.getPropertyValue('--t1');
 for(let i=0;i<6;i++){const s=document.createElement('i');s.className='sp';s.style.left=(t.c+.5)*100/CL+'%';s.style.top=(t.r+.5)*100/RW+'%';const a=Math.random()*6.28,d=24+Math.random()*30;s.style.setProperty('--dx',Math.cos(a)*d+'px');s.style.setProperty('--dy',Math.sin(a)*d+'px');s.style.background=i%2?'#fff':cs;b.appendChild(s);setTimeout(()=>s.remove(),650)}};
FX.float=function(q,txt){const b=G&&G.board;if(!b)return;const f=document.createElement('div');f.className='fl';f.textContent=txt;f.style.left=(q[1]+.5)*100/CL+'%';f.style.top=(q[0]+.5)*100/RW+'%';b.appendChild(f);setTimeout(()=>f.remove(),950)};
FX.confetti=function(){const w=document.createElement('div');w.className='cfw';
 for(let i=0;i<70;i++){const c=document.createElement('i');c.className='cf';c.style.left=Math.random()*100+'%';c.style.background=PAL[i%PAL.length][0];c.style.animationDelay=Math.random()*.6+'s';c.style.animationDuration=1.8+Math.random()*1.6+'s';c.style.setProperty('--r',(Math.random()*720-360)+'deg');c.style.setProperty('--x',(Math.random()*160-80)+'px');w.appendChild(c)}
 document.body.appendChild(w);setTimeout(()=>w.remove(),4200)};

/* ===== área do professor ===== */
const Teach={};
let teacherUntil=0;
function hpin(s){let h=5381;for(let i=0;i<s.length;i++)h=((h<<5)+h+s.charCodeAt(i))>>>0;return String(h)}
Teach.pin=function(cb){
 if(Date.now()<teacherUntil){cb();return}
 Teach._cb=cb;
 modal('<div class="big">🔒</div><h2>Área do professor</h2><p>Digite a senha para continuar.</p><input type="password" id="pin1" autocomplete="off" placeholder="Senha"><button class="btn primary" data-act="pinok" style="margin-top:14px">Entrar</button><button class="btn" data-act="cancel">Cancelar</button>')};
function shakeEl(e){e.classList.add('shake');setTimeout(()=>e.classList.remove('shake'),400)}
/* ---------- editor de modos (Studio) ---------- */
const VL5=['a','e','i','o','u'];
Teach.edit=function(m,idx){closeModals();const c=idx>=0?DB.custom[m][idx]:{};Teach._ed={m:m,idx:idx};
 const M=MODES[m];const names={vog:'Desafio do AEIOU',con:'Hoje é o F',f31:'Estudando o V',f32:'As palavras do texto de hoje'};
 const sel=(id,opts,cur)=>'<select id="'+id+'">'+opts.map(o=>'<option value="'+o[0]+'"'+(String(cur)===String(o[0])?' selected':'')+'>'+o[1]+'</option>').join('')+'</select>';
 let body='<label class="fld"><span>Nome do modo</span><input type="text" id="e_title" maxlength="40" placeholder="Ex.: '+names[m]+'" value="'+esc(c.title||'')+'"></label>';
 const ndLbl={vog:'Peças que atrapalham (tipos diferentes)',con:'Peças que atrapalham (tipos diferentes)',f31:'Sílabas de outras famílias para atrapalhar',f32:'Sílabas aleatórias para atrapalhar'}[m];
 if(m==='vog')body+='<label class="fld"><span>Vogais da missão</span></label><div class="tg" id="e_vog">'+VL5.map(v=>'<button class="'+((c.targets||['a']).indexOf(v)>=0?'on':'')+'" data-act="tg" data-v="'+v+'">'+v.toUpperCase()+'</button>').join('')+'</div>'
  +'<label class="fld"><span>O que atrapalha?</span>'+sel('e_dtype',[['both','Consoantes e outras vogais'],['opp','Só consoantes'],['same','Só outras vogais']],c.dtype||'both')+'</label>'+labSel(c);
 if(m==='con')body+='<label class="fld"><span>Letras da missão</span><input type="text" id="e_con" maxlength="12" placeholder="Ex.: F   ou   P B" value="'+esc((c.targets||[]).join(' ').toUpperCase())+'"><small>Digite 1 a 4 consoantes.</small></label>'
  +'<label class="fld"><span>O que atrapalha?</span>'+sel('e_dtype',[['both','Vogais e outras consoantes'],['opp','Só vogais'],['same','Só outras consoantes']],c.dtype||'both')+'</label>'+labSel(c);
 if(m==='f31')body+='<label class="fld"><span>Família silábica</span><input type="text" id="e_fam" maxlength="40" placeholder="Ex.: V   ou   V F   ou   GU   ou   BR" value="'+esc(c.family||'')+'"><small>Digite uma ou mais famílias (V, CH, QU, BR…) ou liste as sílabas: va ve vi vo vu</small></label>';
 if(m==='f32')body+='<label class="fld"><span>Palavras do dia (uma por linha, com hífen nas sílabas)</span><textarea id="e_words" placeholder="ca-sa&#10;bo-la&#10;pi-pa">'+esc((c.words||[]).join('\n'))+'</textarea><small>Cole o texto do dia e toque em “Separar sílabas”. Você pode corrigir os hífens à mão.</small></label><button class="btn sm" data-act="split">✂️ Separar sílabas</button><div class="prev" id="e_prev">Nenhuma palavra ainda.</div><div class="sw"><span>Só valem as palavras da lista<br><small style="color:var(--mut)">Desligado: qualquer palavra do dicionário conta</small></span><button class="'+(c.strict?'on':'')+'" id="e_strict" data-act="tg"></button></div>';
 const mins=c.mins||8,goal=c.goal||(m==='f32'?Math.max(15,3*(c.words||[]).length):15);
 body+='<div class="sect" style="margin-top:18px">Regras do tabuleiro</div>'
  +'<label class="fld"><span>Tamanho do tabuleiro</span>'+sel('e_size',[[4,'4 × 4 (bem fácil)'],[5,'5 × 5'],[6,'6 × 6 (padrão)'],[7,'7 × 7 (desafio)']],c.size||6)+'</label>'
  +'<label class="fld"><span>'+ndLbl+'</span><input type="number" id="e_nd" min="0" max="8" value="'+(c.nd===undefined?3:c.nd)+'"></label>'
  +'<label class="fld"><span>Tempo: <b id="e_mv">'+mins+'</b> min</span><input type="range" id="e_mins" min="5" max="15" value="'+mins+'" oninput="document.getElementById(\'e_mv\').textContent=this.value"></label>'
  +'<label class="fld"><span>'+(m==='f32'?'Meta: palavras diferentes a formar':'Meta: quantas peças juntar')+'</span><input type="number" id="e_goal" min="3" max="99" value="'+goal+'"></label>';
 modal('<h2>'+(idx>=0?'Editar':'Novo')+' modo</h2><p>'+esc(M.name)+'</p>'+body+'<button class="btn primary" data-act="ttest" style="margin-top:16px">▶ Testar agora</button><div class="row" style="margin-top:10px"><button class="btn" data-act="tsave">💾 Salvar</button><button class="btn" data-act="cancel">Cancelar</button></div>','left');
 if(m==='f32')Teach.preview()};
function labSel(c){return'<label class="fld"><span>Estilo das letras</span><select id="e_lab"><option value="u"'+(c.lab==='u'||!c.lab?' selected':'')+'>MAIÚSCULAS</option><option value="m"'+(c.lab==='m'?' selected':'')+'>MAIÚSCULAS e minúsculas</option><option value="a"'+(c.lab==='a'?' selected':'')+'>Com acentos</option></select></label>'}
Teach.preview=function(){const t=$('#e_words'),p=$('#e_prev');if(!t||!p)return;buildDict();
 const ws=t.value.split(/\n/).map(x=>x.trim()).filter(Boolean);let tot=0,bad=[];
 const unk=[];const parts=ws.map(w=>{const s=w.split('-').filter(Boolean);tot+=s.length;if(s.length<2)bad.push(w);else if(DSET.size&&!DSET.has(norm(s.join(''))))unk.push(s.join(''));return s.join('·')});
 p.innerHTML=ws.length?'<b>'+ws.length+' palavra(s)</b> · '+tot+' sílabas<br>'+parts.map(x=>esc(x)).join(' &nbsp; ')+(unk.length?'<br><span class="bad">Fora do dicionário (confira): '+esc(unk.join(', '))+'</span>':'')+(bad.length?'<br><span class="bad">Sem hífen/2+ sílabas (serão ignoradas): '+esc(bad.join(', '))+'</span>':''):'Nenhuma palavra ainda.'};
Teach.split=function(){const t=$('#e_words');if(!t)return;
 const toks=t.value.toLowerCase().split(/[^a-záéíóúâêôãõàç-]+/).map(x=>x.replace(/^-+|-+$/g,'')).filter(x=>x.replace(/-/g,'').length>=3);
 const seen=new Set(),out=[];toks.forEach(x=>{const k=x.replace(/-/g,'');if(seen.has(k))return;seen.add(k);const s=x.indexOf('-')>=0?x.split('-').filter(Boolean):sylAuto(k);out.push(s.join('-'))});
 t.value=out.join('\n');Teach.preview()};
document.addEventListener('input',e=>{if(e.target&&e.target.id==='e_words')Teach.preview()});
Teach.collect=function(){const m=Teach._ed.m;
 const o={title:($('#e_title').value||'').trim()||'Modo do professor',mins:+$('#e_mins').value||8,goal:Math.max(3,Math.min(99,+$('#e_goal').value||15)),size:+$('#e_size').value||6,nd:Math.max(0,Math.min(8,+$('#e_nd').value||0))};
 if(m==='vog'){o.targets=[...document.querySelectorAll('#e_vog .on')].map(b=>b.dataset.v);if(!o.targets.length){toast('Escolha ao menos uma vogal.');return null}o.lab=$('#e_lab').value;o.dtype=$('#e_dtype').value}
 if(m==='con'){o.targets=norm($('#e_con').value).toLowerCase().split('').filter(ch=>'bcdfghjklmnpqrstvwxyz'.indexOf(ch)>=0).filter((x,i,a)=>a.indexOf(x)===i).slice(0,4);if(!o.targets.length){toast('Digite ao menos uma consoante.');return null}o.lab=$('#e_lab').value;o.dtype=$('#e_dtype').value}
 if(m==='f31'){o.family=($('#e_fam').value||'').trim();if(!o.family){toast('Digite a família silábica.');return null}}
 if(m==='f32'){const ws=$('#e_words').value.split(/\n/).map(x=>x.trim().toLowerCase()).filter(Boolean).map(w=>w.indexOf('-')>=0?w:sylAuto(w).join('-')).filter(w=>w.split('-').filter(Boolean).length>=2);
  o.strict=$('#e_strict').classList.contains('on');if(!ws.length&&o.strict){toast('Digite palavras com 2 ou mais sílabas.');return null}o.words=ws}
 return o};
Teach.save=function(){const {m,idx}=Teach._ed;const o=Teach.collect();if(!o)return;
 if(idx>=0)DB.custom[m][idx]=o;else DB.custom[m].push(o);save();closeModals();if(UI.inStudio)UI.studio();else UI.mode(m);toast('Modo salvo!')};
/* ---------- área do professor (backup / turma) ---------- */
Teach.area=function(){closeModals();modal('<div class="big">👩‍🏫</div><h2>Área do professor</h2><p>Leve seus desafios para outros aparelhos: exporte, e hospede o arquivo <b>desafios.json</b> junto do jogo, ou importe aqui.</p><button class="btn" data-act="texp">⬇️ Exportar desafios (desafios.json)</button><button class="btn" data-act="timp">⬆️ Importar desafios</button><button class="btn" data-act="tpin">🔑 Trocar senha</button><button class="btn danger" data-act="treset">Apagar progresso do jogador atual</button><button class="btn" data-act="cancel">Fechar</button><input type="file" id="impf" accept=".json,application/json" class="hidden">')};
function download(name,text){const b=new Blob([text],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u)},500)}
Teach.acts={
 pinset(){const a=$('#pin1'),b=$('#pin2');if(a.value.length<4||a.value!==b.value){shakeEl(a.value.length<4?a:b);toast(a.value.length<4?'Use ao menos 4 caracteres.':'As senhas não conferem.');return}DB.pin=hpin(a.value);save();teacherUntil=Date.now()+10*60000;closeTop();const cb=Teach._cb;Teach._cb=null;if(cb)cb()},
 pinok(){const a=$('#pin1');if(hpin(a.value)!==(DB.pin||hpin('prof123'))){shakeEl(a);return}teacherUntil=Date.now()+10*60000;closeTop();const cb=Teach._cb;Teach._cb=null;if(cb)cb()},
 tg(d,b){b.classList.toggle('on')},
 split(){Teach.split()},tsave(){Teach.save()},
 ttest(){const o=Teach.collect();if(!o)return;const m=Teach._ed.m;UI.cur=m;closeModals();UI.play(m,{kind:'custom',c:o,from:UI.inStudio?'studio':'mode'})},
 texp(){download('desafios.json',JSON.stringify(DB.custom,null,1))},
 timp(){const f=$('#impf');f.onchange=()=>{const file=f.files[0];if(!file)return;const rd=new FileReader();rd.onload=()=>{try{const j=JSON.parse(rd.result);let n=0;MKEYS.forEach(m=>{(j[m]||[]).forEach(c=>{if(c&&typeof c==='object'){DB.custom[m].push(c);n++}})});save();toast(n+' desafio(s) importado(s).');closeModals();if(UI.inStudio)UI.studio();else if(UI.cur&&$('.trail'))UI.mode(UI.cur)}catch(e){toast('Arquivo inválido.')}};rd.readAsText(file)};f.click()},
 tpin(){closeModals();modal('<h2>🔑 Nova senha</h2><p>Digite a nova senha do professor (mín. 4 caracteres).</p><input type="password" id="pin1" autocomplete="off"><button class="btn primary" data-act="tpinset" style="margin-top:14px">Salvar</button><button class="btn" data-act="cancel">Cancelar</button>')},
 tpinset(){const a=$('#pin1');if(a.value.length<4){shakeEl(a);return}DB.pin=hpin(a.value);save();closeModals();toast('Senha alterada.')},
 treset(){if(confirm('Apagar todo o progresso de '+DB.player+'?')){const p=me();p.prog={};p.inf={};save();closeModals();toast('Progresso apagado.')}}
};
/* ---------- inicialização ---------- */
window.CLASSCH={vog:[],con:[],f31:[],f32:[]};
function boot(){
 UI.welcome();FX.bg();
 fetch('desafios.json',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(j=>{if(j&&typeof j==='object'){MKEYS.forEach(m=>{if(Array.isArray(j[m]))CLASSCH[m]=j[m].filter(c=>c&&typeof c==='object')});if(UI.cur&&$('.trail'))UI.mode(UI.cur)}}).catch(()=>{});
 if('serviceWorker' in navigator&&/^(https:|http:\/\/localhost|http:\/\/127\.)/.test(location.href))navigator.serviceWorker.register('sw.js').catch(()=>{});
 if(window.speechSynthesis)try{speechSynthesis.getVoices()}catch(e){}}
window.addEventListener('error',e=>{try{console.warn('erro',e.message)}catch(_){}});
boot();

